import re

from moler.exceptions import ParsingDone, CommandFailure

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = 'Sylwester Golonka, Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'sylwester.golonka@nokia.com, dawid.gwizdz@gmail.com'


class ConfigRemoteFzmalign(GenericRtg):
    """Configremotefzmalign command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Configremotefzmalign command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ConfigRemoteFzmalign, self).__init__(connection, prompt=prompt, newline_chars=newline_chars,
                                                   runner=runner)
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "config remote fzmalign"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_errors(line)
                self._parse_successful(line)
            except ParsingDone:
                pass
        return super(ConfigRemoteFzmalign, self).on_new_line(line, is_full_line)

    _re_errors = re.compile(r"(?P<ERROR>((Link|RTG link) is not UP)|FZMALIGN finish?ed,.*((sectors failed to align)|(\d+ failed)))")

    def _parse_errors(self, line):
        """
        Parse error cases in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(ConfigRemoteFzmalign._re_errors, line):
            self.current_ret['STATUS'] = 'FAIL'
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    _re_successful = re.compile(r"(?P<SUCCESS>FZMALIGN finished, all sectors successfully aligned)")

    def _parse_successful(self, line):
        """
        Parse line contains successfully status.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(ConfigRemoteFzmalign._re_successful, line):
            self.current_ret['STATUS'] = 'SUCCESS'
            raise ParsingDone


COMMAND_OUTPUT = """
RTG> config remote fzmalign -i
FZMALIGN finished, all sectors successfully aligned
RTG>"""
COMMAND_KWARGS = {'options': '-i'}

COMMAND_RESULT = {'STATUS': 'SUCCESS'}
